import numpy as np, json, os

def find_components(a):
    h,w = a.shape
    seen = np.zeros_like(a, bool); comps=[]
    for i in range(h):
        for j in range(w):
            if a[i,j]==2 and not seen[i,j]:
                stack=[(i,j)]; cells=[]; seen[i,j]=True
                while stack:
                    r,c = stack.pop(); cells.append((r,c))
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            rr,cc=r+dr,c+dc
                            if 0<=rr<h and 0<=cc<w and a[rr,cc]==2 and not seen[rr,cc]:
                                seen[rr,cc]=True; stack.append((rr,cc))
                comps.append(cells)
    return comps

def parse_ts(cells):
    """Return list of (orient, bartop_row, leftcol, stemtip(r,c)) for T's found in component."""
    s = set(cells)
    ts=[]
    used=set()
    # bar: 3 horizontal cells, stem at center above or below
    for (r,c) in cells:
        if all((r,c+k) in s for k in range(3)):
            # avoid double count: only treat leftmost
            if (r,c-1) in s: continue
            if (r-1,c+1) in s and (r+1,c+1) not in s:
                ts.append(dict(orient='U', bartop=r, left=c, tip=(r-1,c+1)))
            elif (r+1,c+1) in s:
                ts.append(dict(orient='D', bartop=r, left=c, tip=(r+1,c+1)))
    return ts

def transform(grid):
    a = np.array(grid); h,w = a.shape
    comps = find_components(a)
    infos=[]
    for cells in comps:
        ts = parse_ts(cells)
        if len(ts)==1:
            t=ts[0]
            infos.append(dict(orient=t['orient'], left=t['left'], tip=t['tip'], comp=cells, multi=False))
        else:
            infos.append(dict(orient=None, left=min(c for r,c in cells), tip=None, comp=cells, multi=True))
    # column quantile
    lefts = sorted(i['left'] for i in infos)
    med = lefts[len(lefts)//2]
    out = np.zeros((3,6), int)
    comp_ids = {id(i['comp']): k for k,i in enumerate(infos)}
    # map cell -> comp index
    cell2comp = {}
    for k,i in enumerate(infos):
        for cell in i['comp']: cell2comp[cell]=k
    for k,i in enumerate(infos):
        cq = 0 if i['left']<=med else 1
        if i['multi']:
            row, color = 2, 1
        else:
            # trace line from tip in pointing direction
            r,c = i['tip']; dr = -1 if i['orient']=='U' else 1
            row, color = 0, (3 if i['orient']=='U' else 1)
            rr = r+dr
            while 0<=rr<h:
                if (rr,c) in cell2comp and cell2comp[(rr,c)]!=k:
                    o = infos[cell2comp[(rr,c)]]['orient']
                    if o == i['orient']:
                        row = 2
                    break
                rr += dr
        out[row, 2*cq + (3 if color==1 else 0)] = color
    return out.tolist()

